// Rotates an array left by `offset` positions.
// For each i in [0, n): b[i] = a[(i + offset) % n].
// Handles empty input by returning an empty vector.
fn rotate(a: Vec<i32>, offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }

    let k = offset % n; // reduce offset to avoid unnecessary wraparound work

    // Pre-allocate output to the same length as input.
    let mut b = Vec::with_capacity(n);

    // b[i] = a[(i + k) % n]
    // Use two linear slices to avoid modulo inside the loop body.
    b.extend_from_slice(&a[k..]);
    b.extend_from_slice(&a[..k]);

    b
}

